/**
 * PersonaGenome 组装器（Genome Assembler）
 *
 * S6: 将心智模型、反模式、诚实边界、决策类型组装为 PersonaGenome
 *
 * 心智模型数量范围：3-6 个（硬编码，引擎自动约束）
 * 反模式数量范围：2-7 个（硬编码，引擎自动约束）
 * 超出上限→截断；不足下限→标记但不补（让 S7 质量门禁拦截）
 *
 * @date 2026-05-08
 */
import type { DecisionType } from './decision-extractor';
import type { MatchedFramework } from './framework-matcher';
import type { AntiPattern } from './anti-pattern-deriver';
/** 心智能智模型数量下限：低于此数质量门禁不通过 */
export declare const MIN_MENTAL_MODELS = 3;
/** 心智模型数量上限：超过此数自动截断 */
export declare const MAX_MENTAL_MODELS = 6;
/** 反模式数量下限 */
export declare const MIN_ANTI_PATTERNS = 2;
/** 反模式数量上限 */
export declare const MAX_ANTI_PATTERNS = 7;
export interface PersonaGenome {
    roleName: string;
    version: string;
    generatedAt: string;
    mentalModels: MentalModelEntry[];
    antiPatterns: AntiPattern[];
    decisionTypes: DecisionType[];
    exdna: ExDNA;
    oceanScores: OceanScores;
    honestyBoundaries: string[];
    meta: {
        sourceCount: number;
        frameworkCoverage: number;
        confidence: 'low' | 'medium' | 'high';
        /** 心智模型数量是否在 [3, 6] 范围内 */
        mentalModelCountInRange: boolean;
        /** 反模式数量是否在 [2, 7] 范围内 */
        antiPatternCountInRange: boolean;
    };
}
export interface MentalModelEntry {
    id: string;
    name: string;
    category: string;
    coreInsight: string;
    applicationNotes: string;
    limitations: string[];
}
/** ExpressionDNA 6 维 1-5 数值（Schema V4.0 的 ExDNA 格式） */
export interface ExDNA {
    directness: 1 | 2 | 3 | 4 | 5;
    evidenceBasis: 1 | 2 | 3 | 4 | 5;
    proactiveness: 1 | 2 | 3 | 4 | 5;
    structure: 1 | 2 | 3 | 4 | 5;
    emotionalTone: 1 | 2 | 3 | 4 | 5;
    verbosity: 1 | 2 | 3 | 4 | 5;
}
/** OCEAN 人格五维 1-5 数值 */
export interface OceanScores {
    openness: number;
    conscientiousness: number;
    extraversion: number;
    agreeableness: number;
    neuroticism: number;
}
/**
 * 从决策类型和心智模型中推导角色的 ExDNA 6 维数值
 *
 * 映射逻辑（不是 1:1：
 *   decisionStyle: analytical→directness高证据Basis高; intuitive→directness低
 *   communicationTone: direct→directness高; diplomatic→directness低
 *   speedPreference: fast→proactiveness高; deliberate→proactiveness低
 *   trustDefault: high→proactiveness高; low→proactiveness低
 *   riskAttitude: risk_seeking→proactiveness高, directness高; risk_averse→proactiveness低
 *
 * 当决策类型中有 critical 级别 → structure 和 evidenceBasis 提高
 * 当反模式包含沟通类 → emotionalTone 下调（更冷峻）
 */
export declare function deriveExDNA(decisionTypes: DecisionType[], antiPatterns: AntiPattern[]): ExDNA;
/**
 * 从 ExDNA 计算 OCEAN 人格分数
 *
 * ⚠️ 此映射基于 ExDNA 各维度的线性近似，并非真实 OCEAN 心理测量——
 *    ExDNA 的 6 维（directness, evidenceBasis...）描述的是工作风格偏好，
 *    不是人格特质。当前映射在小范围（1-5）里区分度有限，
 *    大多数角色落在 2.0-4.0 区间。
 *
 * 待真实 OCEAN 测试数据验证后替换为更好的映射。
 */
export declare function exDNAtoOCEAN(exdna: ExDNA): OceanScores;
/**
 * 组装完整 PersonaGenome
 *
 * 心智模型数量强制约束为 3-6 个
 * 反模式数量强制约束为 2-7 个
 * ExDNA 直接从决策类型和反模式映射，不走字符串中转
 */
export declare function assembleGenome(roleName: string, decisions: DecisionType[], matchedFrameworks: MatchedFramework[], antiPatterns: AntiPattern[]): PersonaGenome;
